// Basalt openvr_api.dll proxy for OpenComposite.
//
// Valve's openvr_api.dll exports five interface accessors that the public OpenVR SDK does not
// declare (LiquidVR, VRControlPanel, VRHeadsetView, VRPaths, VRVirtualDisplay) plus
// VR_GetRuntimePath. Games linked against Valve's internal build, such as Half-Life: Alyx, import
// some of them, so replacing openvr_api.dll with OpenComposite fails at load time. This proxy is
// installed as openvr_api.dll. The linker definition generated by CMakeLists.txt forwards every
// OpenComposite export to openvr_api_opencomposite.dll; this file implements only the exports
// OpenComposite lacks.
//
// Every accessor mirrors Valve's implementation: VR_GetGenericInterface with one fixed version
// string, returning nullptr on failure. OpenComposite aborts the game on interface versions it
// does not implement, so versions it lacks return nullptr here without asking it.

#include <windows.h>

#include <cstdint>
#include <cstring>

namespace {

constexpr wchar_t kOpenCompositeModuleName[] = L"openvr_api_opencomposite.dll";

// Valve's openvr_api.dll requests these exact versions.
constexpr char kControlPanelVersion[] = "IVRControlPanel_006";
constexpr char kHeadsetViewVersion[] = "IVRHeadsetView_001";

using GetGenericInterfaceFunction = void* (*)(const char*, int*);

// Returns the directory of `module` with a trailing backslash, or 0 on failure.
DWORD moduleDirectory(HMODULE module, wchar_t* buffer, DWORD capacity) {
    const DWORD length = GetModuleFileNameW(module, buffer, capacity);
    if (length == 0 || length >= capacity) {
        return 0;
    }
    for (DWORD index = length; index > 0; --index) {
        if (buffer[index - 1] == L'\\' || buffer[index - 1] == L'/') {
            buffer[index] = L'\0';
            return index;
        }
    }
    return 0;
}

HMODULE proxyModule() {
    HMODULE module = nullptr;
    GetModuleHandleExW(
        GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        reinterpret_cast<LPCWSTR>(&proxyModule), &module);
    return module;
}

// The forwarded exports normally loaded OpenComposite already; reuse that instance so the
// accessors and the forwarded functions share one runtime. Otherwise load the copy that sits
// next to this proxy, never one found through the search path.
HMODULE openCompositeModule() {
    if (HMODULE loaded = GetModuleHandleW(kOpenCompositeModuleName)) {
        return loaded;
    }
    wchar_t path[MAX_PATH * 4];
    const DWORD directoryLength = moduleDirectory(proxyModule(), path, MAX_PATH * 4);
    const size_t nameLength = wcslen(kOpenCompositeModuleName);
    if (directoryLength == 0 || directoryLength + nameLength + 1 > MAX_PATH * 4) {
        return nullptr;
    }
    std::memcpy(path + directoryLength, kOpenCompositeModuleName,
                (nameLength + 1) * sizeof(wchar_t));
    return LoadLibraryExW(path, nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
}

void* openCompositeInterface(const char* version) {
    HMODULE module = openCompositeModule();
    if (module == nullptr) {
        return nullptr;
    }
    auto getGenericInterface = reinterpret_cast<GetGenericInterfaceFunction>(
        reinterpret_cast<void*>(GetProcAddress(module, "VR_GetGenericInterface")));
    if (getGenericInterface == nullptr) {
        return nullptr;
    }
    // Valve's accessors pass a null error pointer, but OpenComposite dereferences it when
    // called before VR_Init. Always supply one.
    int error = 0;
    void* object = getGenericInterface(version, &error);
    return error == 0 ? object : nullptr;
}

} // namespace

extern "C" {

void* VRControlPanel() {
    return openCompositeInterface(kControlPanelVersion);
}

void* VRHeadsetView() {
    return openCompositeInterface(kHeadsetViewVersion);
}

// OpenComposite implements none of IVRPaths_001, ILiquidVR_001 or IVRVirtualDisplay_002 and
// aborts the process when asked for an unknown version. Valve's runtime returns nullptr when an
// interface is unavailable, which callers already handle.
void* VRPaths() {
    return nullptr;
}

void* LiquidVR() {
    return nullptr;
}

void* VRVirtualDisplay() {
    return nullptr;
}

// Valve semantics: report the runtime directory, set the required size including the
// terminator, and return an empty string when the buffer is too small. The runtime here is
// OpenComposite, so report the directory that holds it.
bool VR_GetRuntimePath(char* buffer, uint32_t bufferSize, uint32_t* requiredBufferSize) {
    HMODULE module = openCompositeModule();
    wchar_t directory[MAX_PATH * 4];
    DWORD length = module == nullptr ? 0 : moduleDirectory(module, directory, MAX_PATH * 4);
    if (length == 0) {
        return false;
    }
    // Valve returns the directory without a trailing separator.
    directory[length - 1] = L'\0';
    const int required = WideCharToMultiByte(CP_UTF8, 0, directory, -1, nullptr, 0, nullptr,
                                             nullptr);
    if (required <= 0) {
        return false;
    }
    if (requiredBufferSize != nullptr) {
        *requiredBufferSize = static_cast<uint32_t>(required);
    }
    if (buffer != nullptr && bufferSize > 0) {
        if (bufferSize >= static_cast<uint32_t>(required)) {
            WideCharToMultiByte(CP_UTF8, 0, directory, -1, buffer, required, nullptr, nullptr);
        } else {
            buffer[0] = '\0';
        }
    }
    return true;
}

} // extern "C"
